import{_ as t,c as n,j as e,a as r,o}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百二十一章 十类行为的人","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/121第一百二十一章 十类行为的人.md","filePath":"meditation/巴利文大藏经/121第一百二十一章 十类行为的人.md"}'),_={name:"meditation/巴利文大藏经/121第一百二十一章 十类行为的人.md"};function l(s,a,i,d,p,c){return o(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百二十一章-十类行为的人",tabindex:"-1"},[r("第一百二十一章 十类行为的人 "),e("a",{class:"header-anchor",href:"#第一百二十一章-十类行为的人","aria-label":'Permalink to "第一百二十一章 十类行为的人"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部14相应27经/十种业的路径经(界相应/因缘篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，世间的众生如同界（界解释，见第一百零三章）一样，相同特性的事物会聚集、合流到一起，也就是杀生害命的众生与杀生害命的众生聚集、合流到一起；偷盗的众生与偷盗的众生聚集、合流到一起；不检点邪淫的众生与不检点邪淫的众生聚集、合流到一起；说假话的众生与说假话的众生聚集、合流到一起；挑拨离间别人关系的众生与挑拨离间别人关系的众生聚集、合流到一起；说粗暴言语，辱骂、诽谤别人的众生与说粗暴言语，辱骂、诽谤别人的众生聚集、合流到一起；说毫无意义、不正经言语的众生与说毫无意义、不正经言语的众生聚集、合流到一起；贪得无厌的众生与贪得无厌的众生聚集、合流到一起；愤怒伤害别人或自己的众生与愤怒伤害别人或自己的众生聚集、合流到一起；邪知邪见、没有正确见解的众生与邪知邪见、没有正确见解的众生聚集、合流到一起。",-1),e("p",null,"弟子们，同样的道理，不杀生害命的众生与不杀生害命的众生聚集、合流到一起；不偷盗的众生与不偷盗的众生聚集、合流到一起；端正、不邪淫的众生与端正、不邪淫的众生聚集、合流到一起；说真话、不撒谎的众生与说真话、不撒谎的众生聚集、合流到一起；不挑拨离间别人关系的众生与不挑拨离间别人关系的众生聚集、合流到一起；不说粗暴言语，不辱骂、诽谤别人的众生与不说粗暴言语，不辱骂、诽谤别人的众生聚集、合流到一起；不说毫无意义、不正经言语的众生与不说毫无意义、不正经言语的众生聚集、合流到一起；不贪心的众生与不贪心的众生聚集、合流到一起；不愤怒、不伤害别人或自己的众生与不愤怒、不伤害别人或自己的众生聚集、合流到一起；有智慧、有正确见解的众生与有智慧、有正确见解的众生聚集、合流到一起。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(_,[["render",l]]);export{u as __pageData,f as default};
